      Hm_declarative.Empty_context input (Hm_declarative.embed target) typing} ->
    {u : unit | true} @ ghost = fun input answer target typing premise -> ghost_ (
  let use : ((delta : (Copy_spec.node Pref.t @ immutable total ->
      Copy_spec.ty @ immutable total)) @ total ->
    {u : unit | match answer.#inferred_type with
      | None -> false
      | Some ty -> target === Level_mgu_spec.substitute delta ty} ->
    {u : unit | true}) @ total = fun _delta _proof -> () in
  V.principal input answer target typing () true use);;
